// Keep review rows only, drop the ones already alerted (workflow static data), newest first.
const MAX_KEYS = 5000;                       // ids remembered between runs (oldest dropped)
const store = $getWorkflowStaticData('global');
store.seen = store.seen || [];
const seen = new Set(store.seen);
const rows = $input.all().map(i => i.json).filter(r => r.type === 'review' && r.review_id);
const fresh = rows.filter(r => !seen.has(String(r.review_id)));
fresh.sort((a, b) => String(b.created_at || '').localeCompare(String(a.created_at || '')));
for (const r of fresh) store.seen.push(String(r.review_id));
if (store.seen.length > MAX_KEYS) store.seen = store.seen.slice(-MAX_KEYS);
const clip = (s, n) => { s = String(s || '').replace(/<br\s*\/?>/gi, ' ').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const today = new Date().toISOString().slice(0, 10);
const out = fresh.map(r => ({ json: {
  name: r.name || `Listing ${r.id}`,
  rating: Number(r.rating),
  text: clip(r.text, 300),
  created_at: String(r.created_at || '').slice(0, 10),
  reviewer_name: r.reviewer_name || '',
  reviewer_location: r.reviewer_location || '',
  host_reply: clip(r.host_reply, 300),
  reply_status: r.host_reply ? 'replied' : 'unanswered',
  url: r.url || `https://www.airbnb.com/rooms/${r.id}`,
  fetched_on: today,
} }));
return out.length ? out : [{ json: { none: true, reviews_received: rows.length, ids_remembered: store.seen.length } }];
